async function seed() {
  await connectDB();

  // First admin account — this is the ONE time an account is created
  // outside of the admin-only /api/users route. Every account after this
  // must be created by an authenticated admin.
  const adminEmail = process.env.SEED_ADMIN_EMAIL;
  const adminPassword = process.env.SEED_ADMIN_PASSWORD;
  if (adminEmail && adminPassword) {
    const existing = await User.findOne({ email: adminEmail.toLowerCase() });
    if (!existing) {
      await User.create({
        email: adminEmail.toLowerCase(),
        passwordHash: await bcrypt.hash(adminPassword, 12),
        role: "admin",
        status: "active",
      });
      console.log(`[seed] created admin account: ${adminEmail}`);
    } else {
      console.log(`[seed] admin account already exists: ${adminEmail}`);
    }
  }

  const userEmail = process.env.SEED_USER_EMAIL;
  const userPassword = process.env.SEED_USER_PASSWORD;
  if (userEmail && userPassword) {
    const existing = await User.findOne({ email: userEmail.toLowerCase() });
    if (!existing) {
      await User.create({
        email: userEmail.toLowerCase(),
        passwordHash: await bcrypt.hash(userPassword, 12),
        role: "user",
        status: "active",
      });
      console.log(`[seed] created user account: ${userEmail}`);
    } else {
      console.log(`[seed] user account already exists: ${userEmail}`);
    }
  }

  for (const [torturedPhrase, actualPhrase, category] of SAMPLE_PHRASES) {
    await Phrase.updateOne(
      { torturedPhrase },
      { $setOnInsert: { torturedPhrase, actualPhrase, category } },
      { upsert: true }
    );
  }
  console.log(`[seed] ensured ${SAMPLE_PHRASES.length} sample phrases exist`);

  await mongoose.disconnect();
  console.log("[seed] done");
}

seed().catch((err) => {
  console.error(err);
  process.exit(1);
});
